(()=>{const stage=document.querySelector('.stage,.game-stage');if(stage){const snow=document.createElement('div');snow.className='winter-snow';snow.setAttribute('aria-hidden','true');for(let i=0;i<26;i++){const f=document.createElement('span');f.className='winter-flake';f.style.setProperty('--x',`${(i*37)%100}%`);f.style.setProperty('--size',`${3+(i%4)}px`);f.style.setProperty('--duration',`${8+(i%7)*1.1}s`);f.style.setProperty('--delay',`${-(i%13)*1.13}s`);f.style.setProperty('--drift',`${(i%5-2)*18}px`);snow.append(f)}stage.append(snow)}const heading=document.querySelector('.overlay h1');if(heading){const label=document.createElement('span');label.className='winter-label';label.textContent='❄ WINTER UPDATE';heading.before(label)}})();
